DECLARE
  v_data jsonb := $p3c_json${"standard":{"code":"FLL-Naturteich","title_de":"Empfehlungen für Planung, Bau und Instandhaltung von privaten Schwimm- und Badeteichen","title_en":"Guidelines for the Planning, Construction and Maintenance of Private Natural Swimming Pools","version":"2017 (2nd edition, German); English translation 2023/2024"},"worksheets":[{"code":"FLLNT-01","title_de":"Projekteinrichtung & Kundenberatung","title_en":"Project Registration & Customer Brief","phase":1,"archetype":"registration","order_index":1,"description":"Project metadata, client details, and customer consultation checklist (Appendix 3). Captures the initial brief before site or design work begins."},{"code":"FLLNT-02","title_de":"Standortanalyse & Untergrundverhältnisse","title_en":"Site Analysis & Subsoil Conditions","phase":1,"archetype":"data_collection","order_index":2,"description":"Site location, surroundings, subsoil, groundwater, legal duty (enclosure). Applies Appendix 4 existing-systems checklist when remodeling."},{"code":"FLLNT-03","title_de":"Auswahl Naturteich-Typ (I–V)","title_en":"Natural Pool Type Selection (I–V)","phase":2,"archetype":"calculation","order_index":3,"description":"Decision worksheet for natural pool type (Type I through V). Drives the regeneration-technique cascade for downstream design worksheets."},{"code":"FLLNT-04","title_de":"Wasserqualitäts-Anforderungen","title_en":"Water Quality Requirements","phase":2,"archetype":"data_collection","order_index":4,"description":"Fill-up water chemistry (Tab. 7) and swimming-area target values (Tab. 8). Reference test methods per Appendix 1."},{"code":"FLLNT-05","title_de":"Baustoff-Anforderungen","title_en":"Building Material Requirements","phase":2,"archetype":"data_collection","order_index":5,"description":"Concrete, wood, filter substrates, plant substrates, granular materials. Elutable phosphorus test per Appendix 2."},{"code":"FLLNT-06","title_de":"Flächenplanung","title_en":"Space Planning","phase":3,"arc