","label_en":"Fill-up water source","data_type":"enum","unit":null,"is_required":true,"enum_values":[{"value":"tap_water","label_de":"Leitungswasser","label_en":"Tap water","order_index":1,"regulation_reference":"§7.1.1"},{"value":"well_water","label_de":"Brunnenwasser","label_en":"Well water","order_index":2,"regulation_reference":"§7.1.1"},{"value":"rainwater","label_de":"Regenwasser","label_en":"Rainwater","order_index":3,"regulation_reference":"§7.1.1"}],"validation_rules":{"raw":"see Enum_Values: water_source"},"clause_reference":"§7.1.1","description":"Source of fill-up / top-up water: tap, well, or rainwater.","consumer_worksheets":["FLLNT-15"]},{"ws_code":"FLLNT-04","section_code":"C","symbol":"water_test_ammonium","label_de":"Ammonium (Füllwasser)","label_en":"Ammonium (fill-up water)","data_type":"number","unit":"mg/l","is_required":true,"enum_values":null,"validation_rules":{"raw":"≤ 0.5 mg/l per Tab. 7"},"clause_reference":"§7.1.1, Tab.7","description":"Ammonium concentration in fill-up water.","consumer_worksheets":["FLLNT-15"]},{"ws_code":"FLLNT-04","section_code":"C","symbol":"water_test_iron","label_de":"Eisen (Füllwasser)","label_en":"Iron (fill-up water)","data_type":"number","unit":"mg/l","is_required":true,"enum_values":null,"validation_rules":{"raw":"≤ 0.2 mg/l per Tab. 7"},"clause_reference":"§7.1.1, Tab.7","description":"Iron concentration in fill-up water.","consumer_worksheets":["FLLNT-15"]},{"ws_code":"FLLNT-04","section_code":"C","symbol":"water_test_p_total","label_de":"Gesamt-Phosphor (Füllwasser)","label_en":"Total phosphorus (fill-up water)","data_type":"number","unit":"mg/l","is_required":true,"enum_values":null,"validation_rules":{"raw":"≤ 0.03 mg/l per Tab. 7"},"clause_reference":"§7.1.1, Tab.7","description":"Total phosphorus [P_total] in fill-up water.","consumer_worksheets":["FLLNT-15"]},{"ws_code":"FLLNT-04","section_code":"C","symbol":"water_test_orthophosphate","label_de":"Orthophosphat als P (Füllwasser)","label_en":"Orthopho