bel_de":"Hydrobotanik-Typ","label_en":"Hydrobotanical system type","data_type":"enum","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"submergent | emersed"},"clause_reference":"§10.2.1, Tab.10","description":"Submergent (≥ 80 cm water column) or emersed (10–50 cm).","consumer_worksheets":["FLLNT-10","FLLNT-12"]},{"ws_code":"FLLNT-09","section_code":"C","symbol":"hydrobot_water_column","label_de":"Wassersäulenhöhe (Hydrobotanik)","label_en":"Water column height (hydrobotanical)","data_type":"number","unit":"cm","is_required":true,"enum_values":null,"validation_rules":{"raw":"≥ 80 cm submergent; 10–50 cm emersed (Tab. 10)"},"clause_reference":"§10.2.1, Tab.10","description":"Water column height above the substrate layer.","consumer_worksheets":["FLLNT-15"]},{"ws_code":"FLLNT-09","section_code":"C","symbol":"hydrobot_substrate_thickness","label_de":"Substratschichtdicke (Hydrobotanik)","label_en":"Substrate layer thickness (hydrobotanical)","data_type":"number","unit":"cm","is_required":true,"enum_values":null,"validation_rules":{"raw":"10–20 cm submergent; 10–30 cm emersed (Tab. 10)"},"clause_reference":"§10.2.1, Tab.10","description":"Substrate layer thickness in the hydrobotanical zone.","consumer_worksheets":["FLLNT-15"]},{"ws_code":"FLLNT-09","section_code":"C","symbol":"hydrobot_grain_size_max","label_de":"Korngröße max. (Hydrobotanik)","label_en":"Maximum grain size (hydrobotanical)","data_type":"number","unit":"mm","is_required":true,"enum_values":null,"validation_rules":{"raw":"≤ 8 mm (Tab. 10 row 5)"},"clause_reference":"§10.2.1, Tab.10","description":"Substrate grain size — location-of-plant requirement.","consumer_worksheets":null},{"ws_code":"FLLNT-09","section_code":"D","symbol":"hydrobot_feed_rate","label_de":"Beschickungsrate Qmax (Hydrobotanik)","label_en":"Feed rate Qmax (hydrobotanical)","data_type":"number","unit":"m³/(m²·d)","is_required":true,"enum_values":null,"validation_rules":{"raw":"5 m³/(m²·d) submergent and emersed (Tab. 10 row 12)"},"clause_reference":"§10.2.1, Tab.10","description":"Maximum feed rate per Tab. 10.","consumer_worksheets":["FLLNT-11"]},{"ws_code":"FLLNT-10","section_code":"B","symbol":"filter_flow_type","label_de":"Filter-Strömungsart","label_en":"Filter flow type","data_type":"enum","unit":null,"is_required":true,"enum_values":[{"value":"slow","label_de":"Langsamströmung","label_en":"Slow flow","order_index":1,"regulation_reference":"§10.2.2"},{"value":"quick","label_de":"Schnellströmung","label_en":"Quick flow","order_index":2,"regulation_reference":"§10.2.3"}],"validation_rules":{"raw":"slow | quick (depends on pool type)"},"clause_reference":"§10.2.2, §10.2.3","description":"Slow flow (Type III, downstream P-binding required) or quick flow (Type IV).","consumer_worksheets":["FLLNT-11"]},{"ws_code":"FLLNT-10","section_code":"B","symbol":"filter_flow_direction","label_de":"Filter-Strömungsrichtung","label_en":"Filter flow direction","data_type":"enum","unit":null,"is_required":true,"enum_values":[{"value":"vertical_continuous_overflow","label_de":"vertikal, durchgehender Vollüberlauf","label_en":"vertical flow, continuous full-surface overflow","order_index":1,"regulation_reference":"Tab.11, Tab.12"},{"value":"vertical_no_overflow","label_de":"vertikal, ohne Überlauf","label_en":"vertical flow, no overflow","order_index":2,"regulation_reference":"Tab.11, Tab.12"},{"value":"horizontal","label_de":"horizontal","label_en":"horizontal flow","order_index":3,"regulation_reference":"Tab.11, Tab.12"}],"validation_rules":{"raw":"vertical_continuous_overflow | vertical_no_overflow | horizontal"},"clause_reference":"§10.2.2, §10.2.3, Tab.11, Tab.12","description":"Flow direction within filter body, determines applicable Tab. 11/12 column.","consumer_worksheets":null},{"ws_code":"FLLNT-10","section_code":"C","symbol":"filter_water_column","label_de":"Wassersäulenhöhe (Filter)","label_en":"Water column height (filter)","data_type":"number","unit":"cm","is_required":true,"enum_values":null,"validation_rules":{"raw":"≥ 10 cm slow (vertical overflow); ≥ 0 cm quick (vertical overflow)"},"clause_reference":"§10.2.2, §10.2.3, Tab.11, Tab.12","description":"Water column above the filter-effective layer.","consumer_worksheets":null},{"ws_code":"FLLNT-10","section_code":"C","symbol":"filter_layer_thickness","label_de":"Filterwirksame Schichtdicke","label_en":"Filter-effective layer thickness","data_type":"number","unit":"cm","is_required":true,"enum_values":null,"validation_rules":{"raw":"≥ 40 cm slow; ≥ 50 cm quick"},"clause_reference":"§10.2.2, §10.2.3, Tab.11, Tab.12","description":"Thickness of the filter-effective (water-purifying) layer.","consumer_worksheets":null},{"ws_code":"FLLNT-10","section_code":"C","symbol":"filter_grain_size_max","label_de":"Korngröße max. (Filter)","label_en":"Maximum grain size (filter)","data_type":"number","unit":"mm","is_required":true,"enum_values":null,"validation_rules":{"raw":"≤ 16 mm slow; ≤ 32 mm quick"},"clause_reference":"§10.2.2, §10.2.3, Tab.11, Tab.12","description":"Maximum grain size in filter-effective layer.","consumer_worksheets":null},{"ws_code":"FLLNT-10","section_code":"C","symbol":"filter_kf","label_de":"Durchlässigkeitsbeiwert k_f","label_en":"Permeability coefficient k_f","data_type":"number","unit":"m/s","is_required":true,"enum_values":null,"validation_rules":{"raw":"≥ 1e-4 slow; ≥ 1e-3 quick (vertical variants)"},"clause_reference":"§10.2.2, §10.2.3, Tab.11, Tab.12","description":"Permeability coefficient of the filter substrate.","consumer_worksheets":null},{"ws_code":"FLLNT-10","section_code":"D","symbol":"filter_feed_rate_slow_qmax","label_de":"Beschickungsrate Qmax (Filter, langsam)","label_en":"Feed rate Qmax (slow filter)","data_type":"number","unit":"m³/(m²·d)","is_required":false,"enum_values":null,"validation_rules":{"raw":"5 m³/(m²·d) overflow / 8 m³/(m²·d) no-overflow (Tab. 11 row 14)"},"clause_reference":"§10.2.2, Tab.11","description":"Maximum feed rate for slow-flow substrate filter; differs between vertical-continuous-overflow and vertical-no-overflow.","consumer_worksheets":["FLLNT-11"]},{"ws_code":"FLLNT-10","section_code":"D","symbol":"filter_feed_rate_quick_qmin","label_de":"Beschickungsrate Qmin (Filter, schnell)","label_en":"Feed rate Qmin (quick filter)","data_type":"number","unit":"m³/(m²·d)","is_required":false,"enum_values":null,"validation_rules":{"raw":"≥ 15 m³/(m²·d) per Tab. 12 row 14"},"clause_reference":"§10.2.3, Tab.12","description":"Minimum feed rate for quick-flow substrate filter (per experience; smaller permitted if functionality ensured).","consumer_worksheets":["FLLNT-11"]},{"ws_code":"FLLNT-10","section_code":"C","symbol":"filter_layer_tolerance_pct","label_de":"Toleranz Schichtdicke (Filter)","label_en":"Layer thickness tolerance (filter)","data_type":"number","unit":"%","is_required":true,"enum_values":null,"validation_rules":{"raw":"≤ 10 % deviation (Tab. 11/12 row 11)"},"clause_reference":"§10.2.2, §10.2.3, Tab.11, Tab.12","description":"Permitted deviation from specified filter-layer thickness.","consumer_worksheets":null},{"ws_code":"FLLNT-10","section_code":"C","symbol":"filter_frost_resistance","label_de":"Frostbeständigkeit Filter","label_en":"Frost resistance (filter)","data_type":"boolean","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"mandatory"},"clause_reference":"§10.2.2, §10.2.3, Tab.11, Tab.12","description":"Frost resistance of filter substrate.","consumer_worksheets":null},{"ws_code":"FLLNT-10","section_code":"C","symbol":"grain_specific_surface","label_de":"Spez. Kornoberfläche","label_en":"Grain specific surface area (SSA)","data_type":"number","unit":"m²/m³","is_required":true,"enum_values":null,"validation_rules":{"raw":"lookup Tab. 15 by grain class"},"clause_reference":"App.5, Tab.15","description":"Specific surface area of filter grain (per Tab. 15: e.g., 4/8→1200, 8/16→600, 16/32→300 m²/m³).","consumer_worksheets":null},{"ws_code":"FLLNT-10","section_code":"D","symbol":"filter_volume_required","label_de":"Erforderliches Filtervolumen","label_en":"Required filter volume","data_type":"number","unit":"m³","is_required":true,"enum_values":null,"validation_rules":{"raw":"computed: pool_underwater_surface * 50 / grain_specific_surface"},"clause_reference":"§10.2.3, App.5","description":"Required filter volume to meet the 50× colonized-surface rule.","consumer_worksheets":["FLLNT-15"]},{"ws_code":"FLLNT-10","section_code":"D","symbol":"filter_colonized_surface_actual","label_de":"Tatsächliche Bewuchsfläche (Filter)","label_en":"Actual colonizable surface (filter)","data_type":"number","unit":"m²","is_required":true,"enum_values":null,"validation_rules":{"raw":"computed: grain_specific_surface * F_filter * h_filter"},"clause_reference":"App.5","description":"Total grain surface in the filter that can be colonized by biofilm.","consumer_worksheets":["FLLNT-15"]},{"ws_code":"FLLNT-10","section_code":"F","symbol":"filter_50x_rule_met","label_de":"50×-Regel erfüllt","label_en":"50× rule satisfied","data_type":"boolean","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"filter_colonized_surface_actual ≥ 50 × pool_underwater_surface"},"clause_reference":"§10.2.3, App.5","description":"Verifies the colonized filter surface is at least 50 times the underwater pool surface.","consumer_worksheets":["FLLNT-15"]},{"ws_code":"FLLNT-11","section_code":"C","symbol":"circulation_type","label_de":"Zirkulationsart","label_en":"Circulation type","data_type":"text","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"non-empty"},"clause_reference":"§10.3.1","description":"Technical flow regime through the swimming area.","consumer_worksheets":["FLLNT-13"]},{"ws_code":"FLLNT-11","section_code":"C","symbol":"overflow_type","label_de":"Überlauftyp","label_en":"Overflow type","data_type":"text","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"non-empty"},"clause_reference":"§10.3.2","description":"Overflow configuration (skimmer, weir, etc.).","consumer_worksheets":["FLLNT-13"]},{"ws_code":"FLLNT-11","section_code":"C","symbol":"intake_discharge_provided","label_de":"Zu-/Ableitung dimensioniert","label_en":"Intake/discharge dimensioned","data_type":"boolean","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"boolean"},"clause_reference":"§10.3.3","description":"Confirms intake/discharge and feed systems are designed and installed.","consumer_worksheets":["FLLNT-13"]},{"ws_code":"FLLNT-11","section_code":"C","symbol":"physical_chemical_used","label_de":"Physikalisch-chemische Verfahren verwendet","label_en":"Physical/chemical techniques used","data_type":"boolean","unit":null,"is_required":false,"enum_values":null,"validation_rules":{"raw":"may only be supplementary to biological techniques"},"clause_reference":"§10.2.5","description":"Indicates whether supplementary physical or chemical treatment is used.","consumer_worksheets":["FLLNT-15"]},{"ws_code":"FLLNT-12","section_code":"C","symbol":"plant_species_list","label_de":"Pflanzenliste","label_en":"Plant species list","data_type":"json","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"non-empty"},"clause_reference":"§10.4","description":"List of selected plant species by zone and pool type.","consumer_worksheets":["FLLNT-13"]},{"ws_code":"FLLNT-12","section_code":"D","symbol":"planting_completion_date","label_de":"Pflanztermin abgeschlossen","label_en":"Planting completion date","data_type":"date","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"valid date"},"clause_reference":"§10.4.4","description":"Date planting was completed and the system is ready for acceptance inspection.","consumer_worksheets":["FLLNT-13"]},{"ws_code":"FLLNT-12","section_code":"C","symbol":"pre_maturity_care_provided","label_de":"Anwuchspflege geleistet","label_en":"Pre-maturity care provided","data_type":"boolean","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"boolean"},"clause_reference":"§10.4.5","description":"Confirms pre-maturity (establishment) plant care has been provided.","consumer_worksheets":["FLLNT-13","FLLNT-14"]},{"ws_code":"FLLNT-13","section_code":"C","symbol":"acceptance_date","label_de":"Abnahmedatum","label_en":"Acceptance date","data_type":"date","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"valid date"},"clause_reference":"§11.1","description":"Date of the acceptance inspection of the building work.","consumer_worksheets":["FLLNT-15"]},{"ws_code":"FLLNT-13","section_code":"F","symbol":"acceptance_passed","label_de":"Abnahme bestanden","label_en":"Acceptance passed","data_type":"boolean","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"boolean"},"clause_reference":"§11.1","description":"Final acceptance verdict.","consumer_worksheets":["FLLNT-15"]},{"ws_code":"FLLNT-13","section_code":"C","symbol":"defects_noted","label_de":"Mängel-Anmerkungen","label_en":"Defects noted","data_type":"text","unit":null,"is_required":false,"enum_values":null,"validation_rules":{"raw":"free text"},"clause_reference":"§11.2","description":"Any defects recorded; basis for claims-due-to-defects (§11.2).","consumer_worksheets":["FLLNT-15"]},{"ws_code":"FLLNT-14","section_code":"C","symbol":"maintenance_contract_in_place","label_de":"Wartungsvertrag","label_en":"Maintenance contract in place","data_type":"boolean","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"boolean"},"clause_reference":"§12","description":"Confirms a maintenance contract or schedule is in place.","consumer_worksheets":["FLLNT-15"]},{"ws_code":"FLLNT-14","section_code":"C","symbol":"inspection_frequency","label_de":"Prüfintervall","label_en":"Inspection frequency","data_type":"text","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"non-empty"},"clause_reference":"§12.2","description":"Frequency of checks and inspections.","consumer_worksheets":null},{"ws_code":"FLLNT-14","section_code":"C","symbol":"repair_provisions","label_de":"Reparaturvorkehrungen","label_en":"Repair provisions","data_type":"text","unit":null,"is_required":false,"enum_values":null,"validation_rules":{"raw":"free text"},"clause_reference":"§12.4","description":"Provisions for repairs, including allowance for biological re-stabilization (1–2 months) after major water change.","consumer_worksheets":null},{"ws_code":"FLLNT-15","section_code":"F","symbol":"compliance_verdict_overall","label_de":"Gesamt-Konformitätsurteil","label_en":"Overall compliance verdict","data_type":"enum","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"see Enum_Values: compliance_verdict"},"clause_reference":"(cross-cuts)","description":"Aggregate engineering verdict over all phases.","consumer_worksheets":null},{"ws_code":"FLLNT-15","section_code":"C","symbol":"phase_1_gate","label_de":"Phase 1 – Gate","label_en":"Phase 1 gate result","data_type":"enum","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"gate_result enum"},"clause_reference":"§1, §4, §8.1","description":"Pass/fail summary of Phase 1 worksheets (FLLNT-01, FLLNT-02).","consumer_worksheets":null},{"ws_code":"FLLNT-15","section_code":"C","symbol":"phase_2_gate","label_de":"Phase 2 – Gate","label_en":"Phase 2 gate result","data_type":"enum","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"gate_result enum"},"clause_reference":"§5, §6, §7","description":"Pass/fail summary of Phase 2 worksheets (FLLNT-03, 04, 05).","consumer_worksheets":null},{"ws_code":"FLLNT-15","section_code":"C","symbol":"phase_3_gate","label_de":"Phase 3 – Gate","label_en":"Phase 3 gate result","data_type":"enum","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"gate_result enum"},"clause_reference":"§8, §9","description":"Pass/fail summary of Phase 3 worksheets (FLLNT-06, 07, 08).","consumer_worksheets":null},{"ws_code":"FLLNT-15","section_code":"C","symbol":"phase_4_gate","label_de":"Phase 4 – Gate","label_en":"Phase 4 gate result","data_type":"enum","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"gate_result enum"},"clause_reference":"§10","description":"Pass/fail summary of Phase 4 worksheets (FLLNT-09, 10, 11).","consumer_worksheets":null},{"ws_code":"FLLNT-15","section_code":"C","symbol":"phase_5_gate","label_de":"Phase 5 – Gate","label_en":"Phase 5 gate result","data_type":"enum","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"gate_result enum"},"clause_reference":"§10.4","description":"Pass/fail summary of Phase 5 (FLLNT-12).","consumer_worksheets":null},{"ws_code":"FLLNT-15","section_code":"C","symbol":"phase_6_gate","label_de":"Phase 6 – Gate","label_en":"Phase 6 gate result","data_type":"enum","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"gate_result enum"},"clause_reference":"§11, §12","description":"Pass/fail summary of Phase 6 worksheets (FLLNT-13, 14).","consumer_worksheets":null},{"ws_code":"FLLNT-11","section_code":"C","symbol":"treatment_impermissible_used","label_de":"Unzulässige Behandlung verwendet","label_en":"Impermissible treatment used","data_type":"boolean","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"must be false — §10.1 prohibits chlorine, ozone, biocides, heavy metals, silver, copper, UV, sonification"},"clause_reference":"§10.1","description":"True if any treatment from the §10.1 impermissible list (chlorine/chlorine dioxide/ozone, biocides, heavy-metal products, silver/copper-based techniques, UV disinfection, sonification) is used. Must be false for compliance.","consumer_worksheets":["FLLNT-15"]},{"ws_code":"FLLNT-10","section_code":"C","symbol":"aerobic_filtration_confirmed","label_de":"Aerobe Filtration bestätigt","label_en":"Aerobic filtration confirmed","data_type":"boolean","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"must be true — §10.1 mandates aerobic operation to prevent P redissolution"},"clause_reference":"§10.1","description":"Confirms the filtration system operates aerobically as required by §10.1 (avoids phosphate redissolution from anaerobic substrate).","consumer_worksheets":["FLLNT-11","FLLNT-15"]},{"ws_code":"FLLNT-11","section_code":"D","symbol":"overflow_edge_length","label_de":"Überlaufkanten-Länge","label_en":"Overflow edge length","data_type":"number","unit":"m","is_required":true,"enum_values":null,"validation_rules":{"raw":"guide value: 1 % of swimming-area surface in metres"},"clause_reference":"§10.3.1","description":"Required length of overflow edge — guide value 1 % of swimming-area surface area in metres (e.g. 30 m² → 0.3 m). Horizontal tolerance: ±2 mm (±1 mm for edges ≤ 1 m).","consumer_worksheets":["FLLNT-15"]},{"ws_code":"FLLNT-11","section_code":"C","symbol":"splash_water_tank_volume","label_de":"Schwallwasserbehälter-Volumen","label_en":"Splash water tank volume","data_type":"number","unit":"l","is_required":false,"enum_values":null,"validation_rules":{"raw":"≥ 150 l/m² of inundated water surface (§10.3.1)"},"clause_reference":"§10.3.1","description":"Usable volume of the splash water tank (compensating tank), required when rigid overflow weirs are used. Minimum 150 L per m² of inundated water surface.","consumer_worksheets":["FLLNT-15"]},{"ws_code":"FLLNT-04","section_code":"E","symbol":"swimming_test_ammonium","label_de":"Ammonium (Schwimmbereich)","label_en":"Ammonium (swimming area)","data_type":"number","unit":"mg/l","is_required":true,"enum_values":null,"validation_rules":{"raw":"≤ 0.3 mg/l per Tab. 8"},"clause_reference":"§7.1.2, Tab.8","description":"Ammonium concentration in swimming-area water.","consumer_worksheets":["FLLNT-15"]},{"ws_code":"FLLNT-04","section_code":"E","symbol":"swimming_test_p_total","label_de":"Gesamt-Phosphor (Schwimmbereich)","label_en":"Total phosphorus (swimming area)","data_type":"number","unit":"mg/l","is_required":true,"enum_values":null,"validation_rules":{"raw":"≤ 0.03 (I-III) / ≤ 0.01 (IV-V) mg/l per Tab. 8"},"clause_reference":"§7.1.2, Tab.8","description":"Total phosphorus in swimming-area water. Threshold differs by pool type.","consumer_worksheets":["FLLNT-15"]},{"ws_code":"FLLNT-04","section_code":"E","symbol":"swimming_test_hardness","label_de":"Gesamthärte (Schwimmbereich)","label_en":"Total hardness (swimming area)","data_type":"number","unit":"mmol/l","is_required":true,"enum_values":null,"validation_rules":{"raw":"≥ 1.0 mmol/l per Tab. 8"},"clause_reference":"§7.1.2, Tab.8","description":"Total alkaline-earth hardness in swimming area.","consumer_worksheets":["FLLNT-15"]},{"ws_code":"FLLNT-04","section_code":"E","symbol":"swimming_test_conductivity","label_de":"Leitfähigkeit (Schwimmbereich)","label_en":"Conductivity (swimming area)","data_type":"number","unit":"µS/cm","is_required":true,"enum_values":null,"validation_rules":{"raw":"≤ 1000 µS/cm at 20 °C per Tab. 8"},"clause_reference":"§7.1.2, Tab.8","description":"Electrical conductivity at 20 °C in swimming area.","consumer_worksheets":["FLLNT-15"]},{"ws_code":"FLLNT-04","section_code":"E","symbol":"swimming_test_nitrate","label_de":"Nitrat (Schwimmbereich)","label_en":"Nitrate (swimming area)","data_type":"number","unit":"mg/l","is_required":true,"enum_values":null,"validation_rules":{"raw":"≤ 30.0 mg/l per Tab. 8"},"clause_reference":"§7.1.2, Tab.8","description":"Nitrate concentration in swimming-area water.","consumer_worksheets":["FLLNT-15"]},{"ws_code":"FLLNT-04","section_code":"E","symbol":"swimming_test_nitrite","label_de":"Nitrit (Schwimmbereich)","label_en":"Nitrite (swimming area)","data_type":"number","unit":"mg/l","is_required":true,"enum_values":null,"validation_rules":{"raw":"≤ 0.01 mg/l per Tab. 8"},"clause_reference":"§7.1.2, Tab.8","description":"Nitrite concentration in swimming-area water.","consumer_worksheets":["FLLNT-15"]},{"ws_code":"FLLNT-04","section_code":"E","symbol":"swimming_test_orthophosphate","label_de":"Orthophosphat (Schwimmbereich)","label_en":"Orthophosphate as P (swimming area)","data_type":"number","unit":"mg/l","is_required":true,"enum_values":null,"validation_rules":{"raw":"≤ 0.03 (I-III) / ≤ 0.01 (IV-V) mg/l per Tab. 8"},"clause_reference":"§7.1.2, Tab.8","description":"Orthophosphate (as P) in swimming-area water. Threshold differs by pool type.","consumer_worksheets":["FLLNT-15"]},{"ws_code":"FLLNT-04","section_code":"E","symbol":"swimming_test_ph","label_de":"pH-Wert (Schwimmbereich)","label_en":"pH value (swimming area)","data_type":"number","unit":"-","is_required":true,"enum_values":null,"validation_rules":{"raw":"7.0 – 9.0 per Tab. 8"},"clause_reference":"§7.1.2, Tab.8","description":"pH of swimming-area water.","consumer_worksheets":["FLLNT-15"]},{"ws_code":"FLLNT-04","section_code":"E","symbol":"swimming_test_acid_capacity_ks43","label_de":"Säurekapazität KS 4.3 (Schwimmbereich)","label_en":"Acid capacity KS 4.3 (swimming area)","data_type":"number","unit":"mmol/l","is_required":true,"enum_values":null,"validation_rules":{"raw":"≥ 2 mmol/l per Tab. 8"},"clause_reference":"§7.1.2, Tab.8","description":"Acid capacity KS 4.3 in swimming area.","consumer_worksheets":["FLLNT-15"]},{"ws_code":"FLLNT-07","section_code":"C","symbol":"freeboard_water_to_seal","label_de":"Wasserspiegel-Abstand zur Dichtungsoberkante","label_en":"Freeboard: water level to sealing top edge","data_type":"number","unit":"cm","is_required":true,"enum_values":null,"validation_rules":{"raw":"≥ 5 cm below upper edge of sealing system (§9.4)"},"clause_reference":"§9.4","description":"Vertical distance from the consistent water level to the upper edge of the sealing system. Does not apply to technical equipment installed for water extraction.","consumer_worksheets":["FLLNT-13","FLLNT-15"]},{"ws_code":"FLLNT-07","section_code":"C","symbol":"edge_height_tolerance_mm","label_de":"Beckenkanten-Höhentoleranz","label_en":"Edge height tolerance","data_type":"number","unit":"mm","is_required":true,"enum_values":null,"validation_rules":{"raw":"±10 mm absolute deviation from planned nominal height"},"clause_reference":"§9.4","description":"Maximum height deviation at the ends of the edges from the planned nominal height.","consumer_worksheets":["FLLNT-13","FLLNT-15"]},{"ws_code":"FLLNT-11","section_code":"C","symbol":"overflow_horizontal_tolerance_mm","label_de":"Überlaufkanten-Horizontaltoleranz","label_en":"Overflow edge horizontal tolerance","data_type":"number","unit":"mm","is_required":true,"enum_values":null,"validation_rules":{"raw":"±2 mm general; ±1 mm for edges ≤ 1 m (§10.3.1)"},"clause_reference":"§10.3.1","description":"Horizontal deviation of the overflow edge from level.","consumer_worksheets":["FLLNT-13","FLLNT-15"]},{"ws_code":"FLLNT-11","section_code":"B","symbol":"rigid_overflow_used","label_de":"Starrer Überlauf verwendet","label_en":"Rigid overflow weir used","data_type":"boolean","unit":null,"is_required":false,"enum_values":null,"validation_rules":{"raw":"if true, splash water tank is mandatory (§10.3.1)"},"clause_reference":"§10.3.1","description":"Indicates whether a rigid (vs flexible) overflow weir is used. Rigid overflow makes the splash water tank mandatory.","consumer_worksheets":["FLLNT-13"]},{"ws_code":"FLLNT-12","section_code":"C","symbol":"plant_density_submerged_per_m2","label_de":"Pflanzdichte (submers)","label_en":"Plant density — submerged","data_type":"number","unit":"plants/m²","is_required":false,"enum_values":null,"validation_rules":{"raw":"6–10 plants/m² per §10.4.3 (P 0.5 pot plants)"},"clause_reference":"§10.4.3","description":"Plant density for submerged plants, approximate value per m² of planting surface.","consumer_worksheets":["FLLNT-13"]},{"ws_code":"FLLNT-12","section_code":"C","symbol":"plant_density_marsh_small_per_m2","label_de":"Pflanzdichte (klein-mittel Sumpf)","label_en":"Plant density — half-height to tall marsh","data_type":"number","unit":"plants/m²","is_required":false,"enum_values":null,"validation_rules":{"raw":"3–5 plants/m² per §10.4.3"},"clause_reference":"§10.4.3","description":"Plant density for half-height to tall marsh and aquatic plants.","consumer_worksheets":["FLLNT-13"]},{"ws_code":"FLLNT-12","section_code":"C","symbol":"plant_density_marsh_medium_per_m2","label_de":"Pflanzdichte (mittel-hoch Sumpf)","label_en":"Plant density — medium to tall marsh","data_type":"number","unit":"plants/m²","is_required":false,"enum_values":null,"validation_rules":{"raw":"5–7 plants/m² per §10.4.3"},"clause_reference":"§10.4.3","description":"Plant density for medium-height to tall marsh and aquatic plants.","consumer_worksheets":["FLLNT-13"]},{"ws_code":"FLLNT-13","section_code":"C","symbol":"completion_notice_days_advance","label_de":"Vorlauf Fertigstellungsanzeige","label_en":"Completion notice advance (working days)","data_type":"number","unit":"days","is_required":true,"enum_values":null,"validation_rules":{"raw":"≥ 3 working days per §11.1"},"clause_reference":"§11.1","description":"Number of working days the supplier informs the purchaser before a completion date.","consumer_worksheets":["FLLNT-15"]},{"ws_code":"FLLNT-05","section_code":"C","symbol":"materials_biocide_free","label_de":"Materialien biozidfrei","label_en":"Materials biocide-free","data_type":"boolean","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"must be true — §7.2 forbids biocidal or disinfecting materials"},"clause_reference":"§7.2","description":"Confirms that materials installed in or adjacent to the water do not have a biocidal or disinfecting effect on the limnologic biocoenosis.","consumer_worksheets":["FLLNT-15"]},{"ws_code":"FLLNT-07","section_code":"C","symbol":"sealing_biocide_free_biofilm_ok","label_de":"Dichtung biozidfrei und biofilm-tolerant","label_en":"Sealing biocide-free and biofilm-permissive","data_type":"boolean","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"must be true — §9.3 prohibits biocidal sealing treatment"},"clause_reference":"§9.3","description":"Confirms that sealings and protective layers are not biocide-treated and that biofilm can form on the surface.","consumer_worksheets":["FLLNT-15"]}],"equations":[{"ws_code":"FLLNT-10","equation_number":"EQ-01","formula":"filter_colonized_surface_actual >= 50 * pool_underwater_surface","input_symbols":["filter_colonized_surface_actual","pool_underwater_surface"],"output_symbol":"filter_50x_rule_met","clause_reference":"§10.2.3, App.5","description":"50×-Regel: Bewuchsfläche im Filter ≥ 50 × besonnte Unterwasserfläche"},{"ws_code":"FLLNT-10","equation_number":"EQ-02","formula":"filter_colonized_surface_actual = grain_specific_surface * F_filter * h_filter","input_symbols":["grain_specific_surface","F_filter","h_filter"],"output_symbol":"filter_colonized_surface_actual","clause_reference":"App.5","description":"Bewuchsfläche im Filter aus Korngröße, Querschnitt und Höhe"},{"ws_code":"FLLNT-10","equation_number":"EQ-03","formula":"V_filter_required = (pool_underwater_surface * 50) / grain_specific_surface","input_symbols":["pool_underwater_surface","grain_specific_surface"],"output_symbol":"filter_volume_required","clause_reference":"App.5","description":"Erforderliches Filtervolumen aus 50×-Regel"},{"ws_code":"FLLNT-11","equation_number":"EQ-04","formula":"overflow_edge_length = 0.01 * swimming_area_m2","input_symbols":["swimming_area_m2"],"output_symbol":"overflow_edge_length","clause_reference":"§10.3.1","description":"Überlaufkanten-Länge: 1 % der Schwimmbereichsfläche"},{"ws_code":"FLLNT-11","equation_number":"EQ-05","formula":"splash_water_tank_volume >= 150 * pool_underwater_surface","input_symbols":["pool_underwater_surface"],"output_symbol":"splash_water_tank_volume","clause_reference":"§10.3.1","description":"Schwallwasserbehälter-Volumen: ≥ 150 l/m² der überfluteten Wasserfläche"}],"compliance":[{"ws_code":"FLLNT-01","code":"REQ-01","title_de":"Scope applicability","condition":"pool_use_type in ['private_single_household','private_multi_household']","description":"Confirm project is a private natural swimming pool within the scope of these guidelines.","clause_reference":"§1"},{"ws_code":"FLLNT-01","code":"REQ-02","title_de":"Customer consultation","condition":"consultation_checklist_completed == true","description":"Appendix 3 customer-consultation checklist completed before design starts.","clause_reference":"App.3"},{"ws_code":"FLLNT-01","code":"REQ-03","title_de":"Site and subsoil suitable","condition":"Engineer confirms suitability","description":"Site location, surroundings, and subsoil assessed per §8.1.","clause_reference":"§8.1"},{"ws_code":"FLLNT-01","code":"REQ-04","title_de":"Legal duty / enclosure","condition":"enclosure_provided == true OR documented exemption","description":"Legal duty to maintain safety satisfied; enclosure where required by local law.","clause_reference":"§8.1.4"},{"ws_code":"FLLNT-01","code":"REQ-05","title_de":"Operating manual","condition":"operating_manual_provided == true","description":"Operating manual prepared as required by §8.1.5.","clause_reference":"§8.1.5"},{"ws_code":"FLLNT-03","code":"REQ-06","title_de":"Natural pool type declared","condition":"natural_pool_type in ['type_I'..'type_V']","description":"Pool type (I–V) selected and documented per Tab. 1.","clause_reference":"§5, Tab.1"},{"ws_code":"FLLNT-03","code":"REQ-07","title_de":"Regeneration-area share appropriate","condition":"regeneration_area_share meets Tab.1 constraint for chosen type","description":"Regeneration area share complies with the constraints of the selected pool type per Tab. 1.","clause_reference":"§5, §9.6, Tab.1"},{"ws_code":"FLLNT-09","code":"REQ-08","title_de":"Phosphorus-binding stage for slow filter","condition":"if filter_flow_type == 'slow' then p_binding_required == true","description":"Type III / slow-flow substrate filter has downstream P-binding stage per §10.2.2.","clause_reference":"§10.2.2"},{"ws_code":"FLLNT-03","code":"REQ-09","title_de":"Fill-up water meets Tab. 7","condition":"all parameters within Tab.7 ranges","description":"All fill-up water parameters within Tab. 7 limits (ammonium, iron, P_total, hardness, conductivity, manganese, nitrate, orthophosphate, pH, acid capacity).","clause_reference":"§7.1.1, Tab.7"},{"ws_code":"FLLNT-03","code":"REQ-10","title_de":"Swimming-area water meets Tab. 8","condition":"Pass 3a will atomize Tab. 8","description":"All swimming-area water parameters within Tab. 8 target values. Tab. 8 verbatim: ammonium ≤ 0.3, P_total ≤ 0.03 (Type I-III) / ≤ 0.01 (Type IV-V), hardness ≥ 1.0 mmol/l, conductivity ≤ 1000 µS/cm, nitrate ≤ 30.0, nitrite ≤ 0.01, orthophosphate ≤ 0.03 (I-III) / ≤ 0.01 (IV-V), pH 7.0-9.0, KS 4.3 ≥ 2 mmol/l.","clause_reference":"§7.1.2, Tab.8"},{"ws_code":"FLLNT-03","code":"REQ-11","title_de":"Material requirements per §7.2","condition":"all material checks pass","description":"Concrete, wood, filter substrates, plant substrates, and granular materials meet §7.2 / Tab. 9.","clause_reference":"§7.2, Tab.9"},{"ws_code":"FLLNT-03","code":"REQ-12","title_de":"Elutable phosphorus per Appendix 2","condition":"filter_substrate_elutable_p <= 5","description":"Filter substrate elutable phosphorus ≤ 5 mg P/kg per §7.2.3 + Tab. 9, tested via the Appendix 2 normative method (1 M HCl, 2:1 solid-solvent ratio, 24 h at 20±2 °C, per DIN 19529:2009-01).","clause_reference":"§7.2.3, Tab.9, App.2"},{"ws_code":"FLLNT-06","code":"REQ-13","title_de":"Space requirements adequate","condition":"areas defined and consistent with pool type","description":"Swimming, regeneration, and supplementary areas sized per §8.2.","clause_reference":"§8.2"},{"ws_code":"FLLNT-06","code":"REQ-14","title_de":"Excavation","condition":"engineer confirms compliance","description":"Excavation per §9.1: subsoil load-bearing (or compacted/improved); drainage if groundwater or stratum water present; engineering rules ATV DIN 18300, DIN 1054, DIN 18196, DIN 4020, DIN 4124, DIN EN ISO 14688-1; excavation surface non-damaging to designated sealing material.","clause_reference":"§9.1"},{"ws_code":"FLLNT-06","code":"REQ-15","title_de":"Separation of areas","condition":"area_separation_method non-empty","description":"Swimming area and regeneration area separated per §9.2.","clause_reference":"§9.2"},{"ws_code":"FLLNT-06","code":"REQ-16","title_de":"Sealing","condition":"sealing_type selected and method documented","description":"Basin sealing per §9.3.","clause_reference":"§9.3"},{"ws_code":"FLLNT-06","code":"REQ-17","title_de":"Edge design","condition":"edge_design non-empty","description":"Edge / coping designed per §9.4.","clause_reference":"§9.4"},{"ws_code":"FLLNT-06","code":"REQ-18","title_de":"Swimming-area construction","condition":"engineer confirms compliance with §9.5.1-3","description":"Swimming area, ground coverings, entries and exits, walkways per §9.5.","clause_reference":"§9.5"},{"ws_code":"FLLNT-09","code":"REQ-19","title_de":"Hydrobotanical system per Tab. 10","condition":"all Tab. 10 rows met","description":"Water column, substrate thickness, grain size, and feed rate within Tab. 10 ranges.","clause_reference":"§10.2.1, Tab.10"},{"ws_code":"FLLNT-09","code":"REQ-20","title_de":"Substrate filter slow flow per Tab. 11","condition":"all Tab. 11 rows met for selected direction","description":"Slow-flow substrate filter meets Tab. 11 structural requirements (where applicable).","clause_reference":"§10.2.2, Tab.11"},{"ws_code":"FLLNT-09","code":"REQ-21","title_de":"Substrate filter quick flow per Tab. 12","condition":"all Tab. 12 rows met for selected direction","description":"Quick-flow substrate filter meets Tab. 12 structural requirements (where applicable).","clause_reference":"§10.2.3, Tab.12"},{"ws_code":"FLLNT-09","code":"REQ-22","title_de":"50× colonized-surface rule","condition":"filter_50x_rule_met == true","description":"Filter colonized surface ≥ 50 × pool underwater surface (§10.2.3, App. 5).","clause_reference":"§10.2.3, App.5"},{"ws_code":"FLLNT-09","code":"REQ-23","title_de":"Water circulation","condition":"all §10.3 sub-requirements documented","description":"Water circulation, overflow, and intake/discharge designed per §10.3.","clause_reference":"§10.3"},{"ws_code":"FLLNT-09","code":"REQ-24","title_de":"Physical/chemical techniques supplementary only","condition":"if physical_chemical_used then biological technique also present","description":"If physical/chemical techniques are used, they are supplementary to biological methods (§10.2.5).","clause_reference":"§10.2.5"},{"ws_code":"FLLNT-12","code":"REQ-25","title_de":"Plants and planting completed","condition":"all §10.4 sub-requirements met","description":"Plants placed per §10.4; system ready for acceptance per §10.4.4; pre-maturity care provided per §10.4.5.","clause_reference":"§10.4"},{"ws_code":"FLLNT-13","code":"REQ-26","title_de":"Acceptance inspection passed","condition":"acceptance_passed == true OR defects resolved","description":"Building work passed acceptance inspection per §11.1; defects (if any) recorded.","clause_reference":"§11.1"},{"ws_code":"FLLNT-13","code":"REQ-27","title_de":"Maintenance plan in place","condition":"maintenance_contract_in_place == true","description":"Maintenance contract or schedule per §12.1–12.3 in place.","clause_reference":"§12.1-12.3, Tab.13"},{"ws_code":"FLLNT-13","code":"REQ-28","title_de":"Repair provisions and re-stabilization","condition":"engineer confirms allowance for 1–2 month biological stabilization","description":"Repair provisions in place; major water change accounts for 1–2 month re-stabilization (§12.4).","clause_reference":"§12.4"},{"ws_code":"FLLNT-09","code":"REQ-29","title_de":"Impermissible water treatments not used","condition":"treatment_impermissible_used == false","description":"None of the §10.1 impermissible treatments are used: disinfectants (chlorine, chlorine dioxide, ozone), biocides/biocidal products (insecticides, fungicides, algicides), heavy-metal-containing products, silver/copper-based techniques, UV disinfection, or sonification. These are categorical prohibitions, not 'supplementary-only' allowances.","clause_reference":"§10.1"},{"ws_code":"FLLNT-09","code":"REQ-30","title_de":"Aerobic filtration mandated","condition":"aerobic_filtration_confirmed == true","description":"The filtration system operates aerobically to prevent phosphate redissolution from anaerobic substrate.","clause_reference":"§10.1"},{"ws_code":"FLLNT-06","code":"REQ-31","title_de":"Edge design and freeboard per §9.4","condition":"engineer confirms all five §9.4 sub-rules met","description":"Edge design: water level ≥ 5 cm below upper edge of sealing system; sealing protected (e.g. mineral cover ≥ 8 mm grain or solid edging); capillary block prevents water discharge; edge permanently stable; surface water entry prevented; edge height tolerance ±10 mm.","clause_reference":"§9.4"},{"ws_code":"FLLNT-06","code":"REQ-32","title_de":"Sealing biocide-free and biofilm-permissive","condition":"sealing biocide-free and per FLL Abdichtungssysteme; crease tolerances respected","description":"Sealings and protective layers are not biocide-treated; only sealings that allow surface biofilm formation are used (§9.3). Sealing system follows the FLL 'Empfehlungen für Abdichtungssysteme für Gewässer im Garten-, Landschafts- und Sportplatzbau'. Crease tolerances: ≤ 1.0 cm height, ≤ 2.0 m length, ≥ 2.0 m distance between, no crossings (synthetic/elastomer liners only). Stainless-steel pools earthed per VDE 0100-702.","clause_reference":"§9.3"},{"ws_code":"FLLNT-09","code":"REQ-33","title_de":"Overflow weir sizing and tolerance","condition":"overflow_edge_length ≥ 0.01 * swimming_area_m2 AND splash_water_tank_volume ≥ 150 * pool_underwater_surface (if rigid overflow)","description":"Overflow edge length ≥ 1 % of swimming-area surface area (guide value per §10.3.1). Overflow edge horizontal tolerance ±2 mm (±1 mm for edges ≤ 1 m). Splash water tank (mandatory with rigid overflow weirs) provides ≥ 150 l/m² of inundated water surface.","clause_reference":"§10.3.1"}]}$p3c_json$::jsonb;
  v_std uuid;
BEGIN
  -- 1. standard (UPSERT by code)
  INSERT INTO standards (code, title_de, title_en, version)
  SELECT v_data->'standard'->>'code', v_data->'standard'->>'title_de',
         v_data->'standard'->>'title_en', v_data->'standard'->>'version'
  ON CONFLICT (code) DO UPDATE
    SET title_de = excluded.title_de, title_en = excluded.title_en, version = excluded.version;
  SELECT id INTO v_std FROM standards WHERE code = v_data->'standard'->>'code';

  -- 2. worksheet templates (UPSERT by standard_id+code)
  INSERT INTO worksheet_templates (standard_id, code, title_de, title_en, phase, archetype, order_index, description)
  SELECT v_std, w->>'code', w->>'title_de', w->>'title_en',
         (w->>'phase')::int, w->>'archetype', (w->>'order_index')::int, w->>'description'
  FROM jsonb_array_elements(v_data->'worksheets') AS w
  ON CONFLICT (standard_id, code) DO UPDATE
    SET title_de = excluded.title_de, title_en = excluded.title_en, phase = excluded.phase,
        archetype = excluded.archetype, order_index = excluded.order_index, description = excluded.description;

  -- 3. sections: null fields.section_id, wipe + reinsert (no unique constraint on code), resolve parents
  UPDATE fields SET section_id = NULL
   WHERE worksheet_template_id IN (SELECT id FROM worksheet_templates WHERE standard_id = v_std);
  DELETE FROM worksheet_sections
   WHERE worksheet_template_id IN (SELECT id FROM worksheet_templates WHERE standard_id = v_std);

  INSERT INTO worksheet_sections (worksheet_template_id, code, title_de, order_index)
  SELECT wt.id, s->>'code', s->>'title_de', (s->>'order_index')::int
  FROM jsonb_array_elements(v_data->'sections') AS s
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = s->>'ws_code';

  UPDATE worksheet_sections AS child
     SET parent_section_id = parent.id
  FROM jsonb_array_elements(v_data->'sections') AS s
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = s->>'ws_code'
  JOIN worksheet_sections parent ON parent.worksheet_template_id = wt.id AND parent.code = s->>'parent_code'
  WHERE s->>'parent_code' IS NOT NULL
    AND child.worksheet_template_id = wt.id
    AND child.code = s->>'code';

  -- 4. fields (UPSERT by worksheet_template_id+symbol; verification_status NOT touched)
  INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit,
                      is_required, enum_values, validation_rules, clause_reference, description, consumer_worksheets)
  SELECT wt.id,
         (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = wt.id AND ws.code = f->>'section_code' LIMIT 1),
         f->>'symbol', f->>'label_de', f->>'label_en', f->>'data_type', f->>'unit',
         (f->>'is_required')::boolean,
         CASE WHEN jsonb_typeof(f->'enum_values') = 'array' THEN f->'enum_values' ELSE NULL END,
         CASE WHEN jsonb_typeof(f->'validation_rules') = 'object' THEN f->'validation_rules' ELSE NULL END,
         f->>'clause_reference', f->>'description',
         CASE WHEN jsonb_typeof(f->'consumer_worksheets') = 'array'
              THEN ARRAY(SELECT jsonb_array_elements_text(f->'consumer_worksheets')) ELSE NULL END
  FROM jsonb_array_elements(v_data->'fields') AS f
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = f->>'ws_code'
  ON CONFLICT (worksheet_template_id, symbol) DO UPDATE
    SET section_id = excluded.section_id, label_de = excluded.label_de, label_en = excluded.label_en,
        data_type = excluded.data_type, unit = excluded.unit, is_required = excluded.is_required,
        enum_values = excluded.enum_values, validation_rules = excluded.validation_rules,
        clause_reference = excluded.clause_reference, description = excluded.description,
        consumer_worksheets = excluded.consumer_worksheets;

  -- 5. equations (UPSERT by worksheet_template_id+equation_number; verification_status preserved)
  INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, clause_reference, description)
  SELECT wt.id, e->>'equation_number', e->>'formula',
         CASE WHEN jsonb_typeof(e->'input_symbols') = 'array' THEN ARRAY(SELECT jsonb_array_elements_text(e->'input_symbols')) ELSE NULL END,
         e->>'output_symbol', e->>'clause_reference', e->>'description'
  FROM jsonb_array_elements(v_data->'equations') AS e
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = e->>'ws_code'
  ON CONFLICT (worksheet_template_id, equation_number) DO UPDATE
    SET formula = excluded.formula, input_symbols = excluded.input_symbols, output_symbol = excluded.output_symbol,
        clause_reference = excluded.clause_reference, description = excluded.description;

  -- 6. compliance requirements (UPSERT by worksheet_template_id+code)
  INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, condition, description, clause_reference, severity)
  SELECT wt.id, c->>'code', c->>'title_de', c->>'condition', c->>'description', c->>'clause_reference', 'block'
  FROM jsonb_array_elements(v_data->'compliance') AS c
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = c->>'ws_code'
  ON CONFLICT (worksheet_template_id, code) DO UPDATE
    SET title_de = excluded.title_de, condition = excluded.condition, description = excluded.description,
        clause_reference = excluded.clause_reference, severity = excluded.severity;
END
$p3c_do$;
